# S6 step 3: the API names. The request and response members step 2 kept, renamed with every
# reference. Routes, query parameters, anonymous members and messages are hand edits.
#
# Run from the repository root:
#   dotnet run --project scripts/s6-rename -- scripts/s6-rename/step3.map
#
# An anonymous member that inferred its name from one of these (new { x.TenantId }) is first
# named explicitly, so it keeps its old JSON name; those are then renamed by hand.

exclude: ModularCA.Database/Migrations/
exclude: ModularCA.Database/AuditDbContext.cs
exclude: ModularCA.Shared/Entities/Audit
exclude: ModularCA.Shared/Enums/AuditActionType.cs
exclude: ModularCA.Migrate/
exclude: tests/ModularCA.Tests/Core/AuditHashGoldenVectorTests.cs
exclude: tests/ModularCA.Tests/Database/FrozenBaselineTests.cs

